insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$soleil-toujours-mineral-ally-daily-defense-spf-30-5-8-oz$$,
  (select id from public.brands where slug = $$soleil-toujours$$),
  $$Daily Defense Mineral Body Lotion SPF 30 — 5.8 oz$$,
  $$sunscreen$$::public.product_category,
  (select id from public.categories where slug = $$sunscreen$$),
  58,
