insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$nuud-family-pack-deodorant$$,
  (select id from public.brands where slug = $$nuud$$),
  $$Family Pack$$,
  $$deodorant$$::public.product_category,
  (select id from public.categories where slug = $$deodorant$$),
  44.99,
  $$Keep the crew fresh – 72 hours effective - Enough for 9 months of armpit freshness. - ECOCERT-certified. - 100% natural deodorant (71% organic). - Vegan. - Dermatologically tested & approved. - No added fragrance. - Active ingredients: microsilver and zinc oxide.$$,
  $$#2B2B2B$$,
  $$https://nuudcare.com/products/family-pack-deodorant$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/0015/1951/7805/files/SKU_FMPK.png?v=1756991236&width=1200$$,
  4.8,
  100,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;

