insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$nuud-starter-pack-copy$$,
  (select id from public.brands where slug = $$nuud$$),
  $$Starter Pack - Retail$$,
  $$skincare$$::public.product_category,
  (select id from public.categories where slug = $$skincare$$),
  7.43,
  $$Vegan – 72 hours effective - Enough for 7-8 weeks of armpit freshness. - 100% natural deodorant (71% organic). - Only 7 seven ingredients. - Dermatologically tested & approved. - No added fragrance. - Active ingredients: microsilver and zinc oxide.$$,
  $$#2B2B2B$$,
  $$https://nuudcare.com/products/starter-pack-copy$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/0015/1951/7805/files/SKU_STPK-1.webp?v=1758696960&width=1200$$,
  4.7,
  81,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;

