insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$hydrant-no-sugar-variety-pack-30-servings-blood-orange-electrolyte$$,
  (select id from public.brands where slug = $$hydrant$$),
  $$TikTok Shop Hydration - DO NOT USE — 30 Servings / Blood Orange Electrolyte$$,
  $$electrolytes$$::public.product_category,
  (select id from public.categories where slug = $$electrolytes$$),
  44.99,
  $$Rehydrate and recharge with balanced electrolytes and real fruit flavors – no artificial junk. This product is for you if: You want to combat dehydration and can't stand the taste of the other sticks. You feel tired or sluggish even after coffee. You need quick recovery after exercise.$$,
  $$#0E7490$$,
  $$https://drinkhydrant.com/products/no-sugar-variety-pack$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/2720/4792/files/27.png?v=1735882043&width=1200$$,
  4.8,
  100,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;

