insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$melanin-haircare-multi-use-softening-leave-in-conditioner-3-bundle-reserve$$,
  (select id from public.brands where slug = $$melanin-haircare$$),
  $$Multi-Use Softening Leave In Conditioner 3-Pack Reserve$$,
  $$hair$$::public.product_category,
  (select id from public.categories where slug = $$hair$$),
  97.2,
  $$This item is part of the January 2027 Collection Reserve and ships in January 2027. 3-packs in this release include a 10% reserved pricing tier. No additional discount codes may be applied.$$,
  $$#6B3E26$$,
  $$https://melaninhaircare.com/products/multi-use-softening-leave-in-conditioner-3-bundle-reserve$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/0744/7124/4035/files/MUSLIC_three-r_54ab549d-a8eb-4ffc-9997-636efee94ad5.png?v=1781269915&width=1200$$,
  4.6,
  62,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;

