insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$earth-harbor-aqua-aura-reparative-eye-creme$$,
  (select id from public.brands where slug = $$earth-harbor$$),
  $$AQUA AURA Peptide Awaken Eye Cream$$,
  $$skincare$$::public.product_category,
  (select id from public.categories where slug = $$skincare$$),
  26,
  $$A wake-up call for tired eyes, this lightweight yet deeply hydrating eye cream instantly brightens and refreshes. Its blue-green hue helps blur dark circles, while 15 botanical actives smooth, plump, and firm for a revitalized look.$$,
  $$#2A9D8F$$,
  $$https://earthharbor.com/products/aqua-aura-reparative-eye-creme$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/1978/7169/files/AquaAurabadge.jpg?v=1768870599&width=1200$$,
  4.5,
  378,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;

