) values (
  $$earth-harbor-mystic-waters-mineralizing-rescue-mist$$,
  (select id from public.brands where slug = $$earth-harbor$$),
  $$MYSTIC WATERS Electrolyte Calming Toner$$,
  $$electrolytes$$::public.product_category,
  (select id from public.categories where slug = $$electrolytes$$),
  12,
  $$A supercharged toning mist that rescues, calms, and purifies troubled skin—restoring balance, reducing shine, and leaving your complexion refreshed. Your SOS, answered.$$,
  $$#2A9D8F$$,
  $$https://earthharbor.com/products/mystic-waters-mineralizing-rescue-mist$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/1978/7169/files/MysticwaterselectrolytecalmingtonerGreigebackground2oz-1.webp?v=1760562050&width=1200$$,
  4.6,
  347,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;

