insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$evolve-beauty-daily-renew-facial-cream$$,
  (select id from public.brands where slug = $$evolve-beauty$$),
  $$Daily Renew Facial Cream$$,
  $$skincare$$::public.product_category,
  (select id from public.categories where slug = $$skincare$$),
  41,
  $$This multi-award winning moisturiser restores normal to dry skin with a blend of pure organic oils. Organic Argan oil nourishes, natural peptides help to reduce signs of ageing, whilst natural Hyaluronic Acid soothes and hydrates. Delicately fragranced with a soothing hypoallergenic vanilla & coconut natural fragrance.$$,
  $$#7EB8A2$$,
  $$https://evolvebeauty.co.uk/products/daily-renew-facial-cream$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/1089/4204/files/evolve-organic-beauty-moisturizer-daily-renew-facial-cream-1153161845.jpg?v=1768017550&width=1200$$,
  4.7,
  286,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;


