insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$evolve-beauty-monoi-rescue-shampoo$$,
  (select id from public.brands where slug = $$evolve-beauty$$),
  $$Monoi Rescue Natural Shampoo$$,
  $$hair$$::public.product_category,
  (select id from public.categories where slug = $$hair$$),
  18,
  $$An organic hydrating shampoo for dry and colour-treated hair, formulated to restore moisture and shine. With Gardenia Monoi which helps to reduce frizz, whilst adding brilliance and shine for healthier hair.$$,
  $$#7EB8A2$$,
  $$https://evolvebeauty.co.uk/products/monoi-rescue-shampoo$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/1089/4204/files/evolve-organic-beauty-shampoo-monoi-rescue-natural-shampoo-1153161853.jpg?v=1768017729&width=1200$$,
  4.7,
  281,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;


