insert into public.products (
  slug, brand_id, name, category, category_id, price, description, accent,
  affiliate_url, affiliate_network, image_url, rating, review_count, is_published, placed_by
) values (
  $$mad-hippie-triple-c-night-cream-mini$$,
  (select id from public.brands where slug = $$mad-hippie$$),
  $$Triple C Night Cream (mini)$$,
  $$skincare$$::public.product_category,
  (select id from public.categories where slug = $$skincare$$),
  14.99,
  $$A deeply hydrating treatment packed with three forms of vitamin C, potent antioxidants & adaptogens. With 19 cutting-edge actives, this synergistic formula brings dramatically brighter, healthier, smoother looking skin in just one jar! *Now with Cacao (read more below)$$,
  $$#C97B84$$,
  $$https://madhippie.com/products/triple-c-night-cream-mini$$,
  'direct',
  $$https://cdn.shopify.com/s/files/1/1503/5836/files/MH2026-DTCPrimary-TripleCNightCream.jpg?v=1784653663&width=1200$$,
  4.5,
  138,
  true,
  'catalog'
)
on conflict (slug) do update set
  name = excluded.name, price = excluded.price, description = excluded.description,
  image_url = excluded.image_url, affiliate_url = excluded.affiliate_url,
  category = excluded.category, is_published = true;

